select pg_temp.check_it((select v from test_state where k='published')->>'state'='saved'and(select v from test_state where k='published')->'published'='true','"reviewed publication atomic"'::jsonb#>>'{}');
select pg_temp.check_it((select count(*)from public.documents where property_id='ee110000-0000-4000-8000-000000000001')=1,'"exact vector chunks published"'::jsonb#>>'{}');
