select pg_temp.check_it(public.save_knowledge_material('ee110000-0000-4000-8000-000000000012','ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"materialId": "ee110000-0000-4000-8000-000000000010", "previousVersionId": "ee110000-0000-4000-8000-000000000010", "title": "Retained knowledge fixture", "content": "Exact short text.\r\nBOM ﻿ and emoji 🏡", "reason": "Reviewed original fixture"}'::jsonb)->>'state'='source_changed','"concurrent version held"'::jsonb#>>'{}');
select pg_temp.check_it(public.release_knowledge_material('ee110000-0000-4000-8000-000000000031','ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"materialId": "ee110000-0000-4000-8000-000000000010", "versionId": "ee110000-0000-4000-8000-000000000010", "expectedLatestVersionId": "ee110000-0000-4000-8000-000000000010", "expectedActiveVersionId": null, "expectedReleaseId": null, "operation": "publish", "confirmed": true, "reason": "Approve exact synthetic source"}'::jsonb||jsonb_build_object('resultHash',(select result_hash from public.knowledge_embedding_requests where id='ee110000-0000-4000-8000-000000000020')))->>'state'='source_changed','"stale publication baseline held"'::jsonb#>>'{}');
insert into test_state values('withdraw',public.release_knowledge_material('ee110000-0000-4000-8000-000000000032','ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"materialId": "ee110000-0000-4000-8000-000000000010", "versionId": "ee110000-0000-4000-8000-000000000010", "expectedLatestVersionId": "ee110000-0000-4000-8000-000000000011", "expectedActiveVersionId": "ee110000-0000-4000-8000-000000000010", "expectedReleaseId": "ee110000-0000-4000-8000-000000000030", "operation": "withdraw", "confirmed": true, "reason": "Withdraw reviewed synthetic version", "resultHash": null}'::jsonb));
select pg_temp.check_it((select v from test_state where k='withdraw')->'published'='false','"withdrawal retained"'::jsonb#>>'{}');
