create function pg_temp.make_search()returns uuid language plpgsql as $$
declare mid uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();r jsonb;begin
 r:=public.save_knowledge_material(mid,'ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',null,'previousVersionId',null,'title','Negative search fixture','content','A','reason','Explicit synthetic fixture'));
 r:=public.begin_knowledge_search(sid,'ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',mid,'versionId',mid,'contentHash',encode(extensions.digest('A','sha256'),'hex'),'confirmed',true,'reason','Reviewed synthetic fixture'),jsonb_build_object('model','text-embedding-3-small','dimensions',1536,'recipe','lossless-utf8-4096-v1','contentHash',encode(extensions.digest('A','sha256'),'hex'),'chunks',jsonb_build_array('A')));
 if r->>'state'<>'saved'then raise exception 'Fixture preparation failed';end if;return sid;
end$$;
do $$declare sid uuid;claim jsonb;receipt jsonb;bad jsonb;idx int;result jsonb;entry public.knowledge_embedding_requests;mid uuid;begin
 select v into receipt from test_state where k='receipt';
 for idx in 1..7 loop
  sid:=pg_temp.make_search();claim:=public.claim_knowledge_search(sid);
  bad:=case idx when 1 then jsonb_set(receipt,'{response,data,0,index}','1')when 2 then jsonb_set(receipt,'{response,data,0,index}','0.5')when 3 then jsonb_set(receipt,'{response,data,0,embedding}','[1]')when 4 then jsonb_set(receipt,'{response,data,0,embedding,0}','"NaN"')when 5 then jsonb_set(receipt,'{response,data,0,embedding,0}','0')when 6 then jsonb_set(receipt,'{response,model}','"other-model"')else jsonb_set(receipt,'{response,data}','[]')end;
  perform public.record_knowledge_search_result(sid,(claim->>'claimToken')::uuid,bad);
  result:=public.validate_knowledge_search(sid,(select result_hash from public.knowledge_embedding_requests where id=sid));
  perform pg_temp.check_it(result->>'state'='held','invalid receipt held case '||idx);
  perform pg_temp.check_it((select raw_result=bad from public.knowledge_embedding_requests where id=sid),'invalid raw receipt retained case '||idx);
  perform pg_temp.check_it(public.claim_knowledge_search(sid)->>'state'='held','invalid receipt never reinvoked case '||idx);
 end loop;
 sid:=pg_temp.make_search();claim:=public.claim_knowledge_search(sid);select *into entry from public.knowledge_embedding_requests where id=sid;
 result:=public.control_knowledge_search(gen_random_uuid(),entry.property_id,entry.actor_id,jsonb_build_object('searchId',sid,'operation','stop','expectedRevision',entry.revision,'reason','Stop synthetic in flight invocation'));
 perform pg_temp.check_it(result->>'state'='saved','stop in flight');
 perform public.record_knowledge_search_result(sid,(claim->>'claimToken')::uuid,receipt);
 perform pg_temp.check_it(public.validate_knowledge_search(sid,(select result_hash from public.knowledge_embedding_requests where id=sid))->>'state'='stopped','late receipt cannot revive stopped work');
 perform pg_temp.check_it((select raw_result=receipt from public.knowledge_embedding_requests where id=sid),'late receipt remains retained');
 sid:=pg_temp.make_search();claim:=public.claim_knowledge_search(sid);select *into entry from public.knowledge_embedding_requests where id=sid;
 perform pg_temp.check_it(public.control_knowledge_search(gen_random_uuid(),entry.property_id,entry.actor_id,jsonb_build_object('searchId',sid,'operation','recover','expectedRevision',entry.revision,'reason','Check in flight invocation'))->>'state'='still_running','early recovery does not steal claim');
 update public.knowledge_embedding_requests set started_at=clock_timestamp()-interval'2 minutes'where id=sid;select *into entry from public.knowledge_embedding_requests where id=sid;
 perform public.control_knowledge_search(gen_random_uuid(),entry.property_id,entry.actor_id,jsonb_build_object('searchId',sid,'operation','recover','expectedRevision',entry.revision,'reason','Review uncertain invocation'));
 perform pg_temp.check_it(public.claim_knowledge_search(sid)->>'state'='held','unknown outcome cannot invoke again');
 perform public.record_knowledge_search_result(sid,(claim->>'claimToken')::uuid,receipt);
 perform pg_temp.check_it(public.validate_knowledge_search(sid,(select result_hash from public.knowledge_embedding_requests where id=sid))->>'state'='ready','late valid receipt can be validated after uncertain recovery');
 sid:=pg_temp.make_search();update public.profiles set role=null where id='11111111-1111-1111-1111-111111111111';
 perform pg_temp.check_it(public.claim_knowledge_search(sid)->>'state'='held','current manager role rechecked at claim');
 perform pg_temp.check_it(public.save_knowledge_material(gen_random_uuid(),'ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{}')->>'state'='forbidden','missing manager role cannot mutate');
 update public.profiles set role='admin'where id='11111111-1111-1111-1111-111111111111';
 sid:=pg_temp.make_search();select material_id into mid from public.knowledge_embedding_requests where id=sid;
 perform public.save_knowledge_material(gen_random_uuid(),'ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',mid,'previousVersionId',mid,'title','New version before invocation','content','B','reason','Revised exact synthetic source'));
 perform pg_temp.check_it(public.claim_knowledge_search(sid)->>'state'='held','changed latest version stops old queued invocation');
end$$;
