 select gen_random_uuid(),'ee110000-0000-4000-8000-000000000010','ee110000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111',null,'History fixture '||n,'Retained fixture',encode(extensions.digest('Retained fixture','sha256'),'hex'),'{}'from generate_series(1,1001)n;
