insert into test_state values('cancelled',public.cancel_unused_knowledge_decision('ee110000-0000-4000-8000-000000000090','ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Explicitly cancel unsent fixture')));
select pg_temp.check_it(v->>'state'='cancelled','unused request identity cancelled')from test_state where k='cancelled';
select pg_temp.check_it(public.save_knowledge_material('ee110000-0000-4000-8000-000000000090','ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"materialId":null,"previousVersionId":null,"title":"Delayed request","content":"Delayed content","reason":"Original delayed request"}')->>'state'='decision_cancelled','cancelled request cannot arrive late and save');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee110000-0000-4000-8000-000000000090','ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Explicitly cancel unsent fixture'))->>'state'='cancelled','lost cancellation reply safely repeats');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee110000-0000-4000-8000-000000000010','ee110000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Check already saved fixture'))->>'state'='replayed','cancellation recovers an already saved source instead');
select 84 as passed_assertions;
ROLLBACK;
